INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT114-S1-Q18$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Background$batch13$, $batch13$Insurers set premiums from risk factors, and premiums rise with risk. Age and accident history matter.$batch13$), (1, $batch13$Conclusion$batch13$, $batch13$Premiums should also rise with how often a person drives.$batch13$), (2, $batch13$Evidence$batch13$, $batch13$A person's chance of a mishap rises in proportion to how often that person drives.$batch13$), (3, $batch13$Evaluate$batch13$, $batch13$"Yet" turns from background to the author's own claim. "After all" then gives the reason for it. Why should premiums rise with driving frequency? Because risk rises with frequency, and premiums track risk. Nothing is built on the frequency claim, so it's the conclusion.$batch13$), (4, $batch13$Goal$batch13$, $batch13$The claim is the conclusion.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT114-S1-Q18$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$This is the most popular trap. A premise supports something else. This claim is what the "After all" sentence supports.$batch13$), ($batch13$B$batch13$, $batch13$It's the author's claim, and "After all" introduces the reason for it.$batch13$), ($batch13$C$batch13$, $batch13$It isn't evidence for anything. It's what the evidence supports.$batch13$), ($batch13$D$batch13$, $batch13$No objection is anticipated or blocked.$batch13$), ($batch13$E$batch13$, $batch13$It doesn't clarify any term. It makes a new claim about premiums.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT114-S1-Q18$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
